def shortestBridge(grid: list[list[int]]) -> int:
    n = len(grid)
    from collections import deque
    q = deque()
    found = False
    def dfs(r, c):
        grid[r][c] = 2
        q.append((r, c, 0))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 1:
                dfs(nr, nc)
    for r in range(n):
        if found: break
        for c in range(n):
            if grid[r][c] == 1:
                dfs(r, c)
                found = True
                break
    while q:
        r, c, d = q.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if grid[nr][nc] == 1: return d
                if grid[nr][nc] == 0:
                    grid[nr][nc] = 2
                    q.append((nr, nc, d + 1))
    return 0

